function runMapIndices(mode: RunMode | undefined): number[] {
  return mode === 'quick' ? QUICK_FLIGHT_MAP_INDICES : alphaMaps.map((_map, index) => index);
}

function runDistrictOrdinal(mode: RunMode | undefined, mapIndex: number): number {
  const index = runMapIndices(mode).indexOf(mapIndex);
  return index >= 0 ? index + 1 : 1;
}

function nextRunMapIndex(mode: RunMode | undefined, mapIndex: number): number | undefined {
  const indices = runMapIndices(mode);
  return indices[indices.indexOf(mapIndex) + 1];
}
